"""A small Flask API for managing per-user tasks."""

import base64
from datetime import datetime, timedelta, timezone
from functools import wraps
import hashlib
import hmac
import json
import os
import sqlite3

from flask import Flask, g, jsonify, request
from werkzeug.security import check_password_hash, generate_password_hash


app = Flask(__name__)
app.config.update(
    JWT_SECRET_KEY=os.environ.get("JWT_SECRET_KEY", "development-secret-change-me"),
    JWT_EXPIRATION_SECONDS=3600,
)

DATABASE = os.environ.get("DATABASE", "todos.db")


def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def init_db():
    """Create the schema and migrate task databases created before authentication."""
    with get_db() as conn:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS users ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  username TEXT NOT NULL UNIQUE,"
            "  password_hash TEXT NOT NULL"
            ")"
        )
        conn.execute(
            "CREATE TABLE IF NOT EXISTS tasks ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  title TEXT NOT NULL,"
            "  status TEXT NOT NULL DEFAULT 'pending',"
            "  created_at TEXT NOT NULL,"
            "  owner_id INTEGER REFERENCES users(id)"
            ")"
        )

        columns = {row["name"] for row in conn.execute("PRAGMA table_info(tasks)")}
        if "owner_id" not in columns:
            # Nullable ownership preserves existing tasks without assigning them to a user.
            conn.execute(
                "ALTER TABLE tasks ADD COLUMN owner_id INTEGER REFERENCES users(id)"
            )
        conn.execute("CREATE INDEX IF NOT EXISTS idx_tasks_owner_id ON tasks(owner_id)")
        conn.commit()


def _base64url_encode(value: bytes) -> str:
    return base64.urlsafe_b64encode(value).rstrip(b"=").decode("ascii")


def _base64url_decode(value: str) -> bytes:
    return base64.urlsafe_b64decode(value + "=" * (-len(value) % 4))


def create_token(user_id: int) -> str:
    header = _base64url_encode(
        json.dumps({"alg": "HS256", "typ": "JWT"}, separators=(",", ":")).encode()
    )
    expires_at = datetime.now(timezone.utc) + timedelta(
        seconds=app.config["JWT_EXPIRATION_SECONDS"]
    )
    payload = _base64url_encode(
        json.dumps(
            {"sub": user_id, "exp": int(expires_at.timestamp())}, separators=(",", ":")
        ).encode()
    )
    signing_input = f"{header}.{payload}".encode("ascii")
    signature = hmac.new(
        app.config["JWT_SECRET_KEY"].encode(), signing_input, hashlib.sha256
    ).digest()
    return f"{header}.{payload}.{_base64url_encode(signature)}"


def decode_token(token: str) -> int:
    try:
        header_part, payload_part, signature_part = token.split(".")
        signing_input = f"{header_part}.{payload_part}".encode("ascii")
        supplied_signature = _base64url_decode(signature_part)
        expected_signature = hmac.new(
            app.config["JWT_SECRET_KEY"].encode(), signing_input, hashlib.sha256
        ).digest()
        if not hmac.compare_digest(supplied_signature, expected_signature):
            raise ValueError("invalid signature")

        header = json.loads(_base64url_decode(header_part))
        payload = json.loads(_base64url_decode(payload_part))
        if header.get("alg") != "HS256" or header.get("typ") != "JWT":
            raise ValueError("invalid header")
        if not isinstance(payload.get("exp"), int):
            raise ValueError("invalid expiry")
        if payload["exp"] <= int(datetime.now(timezone.utc).timestamp()):
            raise ValueError("expired token")
        user_id = payload.get("sub")
        if not isinstance(user_id, int) or isinstance(user_id, bool):
            raise ValueError("invalid subject")
        return user_id
    except (KeyError, TypeError, ValueError, UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError("invalid token") from None


def auth_required(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        authorization = request.headers.get("Authorization", "")
        scheme, separator, token = authorization.partition(" ")
        if not separator or scheme.lower() != "bearer" or not token.strip():
            return jsonify({"error": "authentication required"}), 401

        try:
            user_id = decode_token(token.strip())
        except ValueError:
            return jsonify({"error": "invalid token"}), 401

        with get_db() as conn:
            user = conn.execute("SELECT id FROM users WHERE id = ?", (user_id,)).fetchone()
        if user is None:
            return jsonify({"error": "invalid token"}), 401
        g.user_id = user_id
        return view(*args, **kwargs)

    return wrapped


def create_user(username: str, password: str) -> dict:
    password_hash = generate_password_hash(password)
    with get_db() as conn:
        cursor = conn.execute(
            "INSERT INTO users (username, password_hash) VALUES (?, ?)",
            (username, password_hash),
        )
        conn.commit()
        return {"id": cursor.lastrowid, "username": username}


def create_task(title: str, owner_id: int) -> dict:
    with get_db() as conn:
        now = datetime.now(timezone.utc).isoformat()
        cursor = conn.execute(
            "INSERT INTO tasks (title, status, created_at, owner_id) "
            "VALUES (?, 'pending', ?, ?)",
            (title, now, owner_id),
        )
        conn.commit()
        return {
            "id": cursor.lastrowid,
            "title": title,
            "status": "pending",
            "created_at": now,
            "owner_id": owner_id,
        }


def get_tasks(owner_id: int):
    with get_db() as conn:
        rows = conn.execute(
            "SELECT * FROM tasks WHERE owner_id = ? ORDER BY created_at DESC, id DESC",
            (owner_id,),
        ).fetchall()
        return [dict(row) for row in rows]


def get_task(task_id: int, owner_id: int) -> dict | None:
    with get_db() as conn:
        row = conn.execute(
            "SELECT * FROM tasks WHERE id = ? AND owner_id = ?", (task_id, owner_id)
        ).fetchone()
        return dict(row) if row else None


def update_task(
    task_id: int,
    owner_id: int,
    title: str | None = None,
    status: str | None = None,
) -> dict | None:
    if get_task(task_id, owner_id) is None:
        return None
    with get_db() as conn:
        updates = []
        params = []
        if title is not None:
            updates.append("title = ?")
            params.append(title)
        if status is not None:
            updates.append("status = ?")
            params.append(status)
        if updates:
            params.extend((task_id, owner_id))
            conn.execute(
                f"UPDATE tasks SET {', '.join(updates)} WHERE id = ? AND owner_id = ?",
                params,
            )
            conn.commit()
    return get_task(task_id, owner_id)


@app.route("/auth/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")
    if not isinstance(username, str) or not username.strip():
        return jsonify({"error": "username is required"}), 400
    if not isinstance(password, str) or not password:
        return jsonify({"error": "password is required"}), 400

    try:
        user = create_user(username.strip(), password)
    except sqlite3.IntegrityError:
        return jsonify({"error": "username already exists"}), 409
    return jsonify(user), 201


@app.route("/auth/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")
    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({"error": "invalid username or password"}), 401

    with get_db() as conn:
        user = conn.execute(
            "SELECT id, password_hash FROM users WHERE username = ?",
            (username.strip(),),
        ).fetchone()
    if user is None or not check_password_hash(user["password_hash"], password):
        return jsonify({"error": "invalid username or password"}), 401
    return jsonify({"token": create_token(user["id"])})


@app.route("/tasks", methods=["GET"])
@auth_required
def list_tasks():
    return jsonify(get_tasks(g.user_id))


@app.route("/tasks", methods=["POST"])
@auth_required
def add_task():
    data = request.get_json(silent=True) or {}
    title = data.get("title")
    if not isinstance(title, str) or not title.strip():
        return jsonify({"error": "title is required"}), 400
    task = create_task(title.strip(), g.user_id)
    return jsonify(task), 201


@app.route("/tasks/<int:task_id>", methods=["GET"])
@auth_required
def show_task(task_id: int):
    task = get_task(task_id, g.user_id)
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.route("/tasks/<int:task_id>", methods=["PUT"])
@auth_required
def edit_task(task_id: int):
    data = request.get_json(silent=True) or {}
    if "title" in data and (
        not isinstance(data["title"], str) or not data["title"].strip()
    ):
        return jsonify({"error": "title must be a non-empty string"}), 400
    if "status" in data and not isinstance(data["status"], str):
        return jsonify({"error": "status must be a string"}), 400

    task = update_task(
        task_id,
        g.user_id,
        title=data["title"].strip() if "title" in data else None,
        status=data.get("status"),
    )
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


init_db()


if __name__ == "__main__":
    app.run(debug=True)

import sqlite3

import pytest
from werkzeug.security import check_password_hash

import app as task_app


@pytest.fixture()
def client(tmp_path, monkeypatch):
    monkeypatch.setattr(task_app, "DATABASE", str(tmp_path / "tasks.db"))
    task_app.app.config.update(
        TESTING=True,
        JWT_SECRET_KEY="test-secret",
        JWT_EXPIRATION_SECONDS=3600,
    )
    task_app.init_db()
    return task_app.app.test_client()


def register(client, username="alice", password="secret"):
    return client.post(
        "/auth/register", json={"username": username, "password": password}
    )


def auth_headers(client, username="alice", password="secret"):
    register(client, username, password)
    response = client.post(
        "/auth/login", json={"username": username, "password": password}
    )
    return {"Authorization": f"Bearer {response.get_json()['token']}"}


def test_register_creates_user_with_hashed_password(client):
    response = register(client)

    assert response.status_code == 201
    assert response.get_json() == {"id": 1, "username": "alice"}
    with task_app.get_db() as conn:
        user = conn.execute("SELECT * FROM users WHERE username = 'alice'").fetchone()
    assert user["password_hash"] != "secret"
    assert check_password_hash(user["password_hash"], "secret")


@pytest.mark.parametrize(
    "payload",
    [
        {},
        {"username": "", "password": "secret"},
        {"username": 1, "password": "secret"},
        {"username": "alice", "password": ""},
        {"username": "alice", "password": None},
    ],
)
def test_register_validates_credentials(client, payload):
    response = client.post("/auth/register", json=payload)

    assert response.status_code == 400
    assert "error" in response.get_json()


def test_register_rejects_duplicate_username(client):
    assert register(client).status_code == 201

    response = register(client, password="different")

    assert response.status_code == 409


def test_login_returns_token_accepted_by_task_routes(client):
    register(client)

    login = client.post(
        "/auth/login", json={"username": "alice", "password": "secret"}
    )

    assert login.status_code == 200
    token = login.get_json()["token"]
    assert len(token.split(".")) == 3
    assert client.get(
        "/tasks", headers={"Authorization": f"Bearer {token}"}
    ).status_code == 200


@pytest.mark.parametrize(
    "payload",
    [
        {},
        {"username": "alice", "password": "wrong"},
        {"username": "unknown", "password": "secret"},
    ],
)
def test_login_rejects_invalid_credentials(client, payload):
    register(client)

    response = client.post("/auth/login", json=payload)

    assert response.status_code == 401


@pytest.mark.parametrize(
    "method,path",
    [
        ("get", "/tasks"),
        ("post", "/tasks"),
        ("get", "/tasks/1"),
        ("put", "/tasks/1"),
    ],
)
def test_task_routes_require_authentication(client, method, path):
    response = getattr(client, method)(path, json={} if method in {"post", "put"} else None)

    assert response.status_code == 401


@pytest.mark.parametrize(
    "authorization",
    ["Bearer not-a-jwt", "Basic abc", "Bearer ", "Bearer x.y.z"],
)
def test_task_routes_reject_invalid_tokens(client, authorization):
    response = client.get("/tasks", headers={"Authorization": authorization})

    assert response.status_code == 401


def test_create_and_get_task(client):
    headers = auth_headers(client)
    response = client.post("/tasks", json={"title": "Write tests"}, headers=headers)

    assert response.status_code == 201
    task = response.get_json()
    assert task["title"] == "Write tests"
    assert task["status"] == "pending"
    assert task["owner_id"] == 1
    assert task["created_at"]
    assert client.get(f"/tasks/{task['id']}", headers=headers).get_json() == task


def test_list_tasks_newest_first(client):
    headers = auth_headers(client)
    first = client.post("/tasks", json={"title": "First"}, headers=headers).get_json()
    second = client.post("/tasks", json={"title": "Second"}, headers=headers).get_json()

    assert [task["id"] for task in client.get("/tasks", headers=headers).get_json()] == [
        second["id"],
        first["id"],
    ]


def test_update_task(client):
    headers = auth_headers(client)
    task_id = client.post("/tasks", json={"title": "Old"}, headers=headers).get_json()["id"]

    response = client.put(
        f"/tasks/{task_id}",
        json={"title": "New", "status": "complete"},
        headers=headers,
    )

    assert response.status_code == 200
    assert response.get_json()["title"] == "New"
    assert response.get_json()["status"] == "complete"


def test_users_only_see_and_update_their_own_tasks(client):
    alice_headers = auth_headers(client, "alice")
    alice_task = client.post(
        "/tasks", json={"title": "Alice task"}, headers=alice_headers
    ).get_json()
    bob_headers = auth_headers(client, "bob")
    bob_task = client.post(
        "/tasks", json={"title": "Bob task"}, headers=bob_headers
    ).get_json()

    assert client.get("/tasks", headers=alice_headers).get_json() == [alice_task]
    assert client.get("/tasks", headers=bob_headers).get_json() == [bob_task]
    assert client.get(f"/tasks/{alice_task['id']}", headers=bob_headers).status_code == 404
    assert client.put(
        f"/tasks/{alice_task['id']}",
        json={"status": "complete"},
        headers=bob_headers,
    ).status_code == 404
    assert client.get(f"/tasks/{alice_task['id']}", headers=alice_headers).get_json()[
        "status"
    ] == "pending"


@pytest.mark.parametrize(
    "payload", [{}, {"title": ""}, {"title": "   "}, {"title": None}, {"title": 1}]
)
def test_create_requires_title(client, payload):
    response = client.post("/tasks", json=payload, headers=auth_headers(client))

    assert response.status_code == 400
    assert "error" in response.get_json()


@pytest.mark.parametrize("method", ["get", "put"])
def test_missing_task_returns_404(client, method):
    kwargs = {"json": {"status": "complete"}} if method == "put" else {}
    response = getattr(client, method)(
        "/tasks/999", headers=auth_headers(client), **kwargs
    )

    assert response.status_code == 404
    assert response.get_json() == {"error": "task not found"}


def test_init_db_migrates_existing_tasks_without_data_loss(tmp_path, monkeypatch):
    database = tmp_path / "legacy.db"
    with sqlite3.connect(database) as conn:
        conn.execute(
            "CREATE TABLE tasks ("
            "id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, "
            "status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL)"
        )
        conn.execute(
            "INSERT INTO tasks (title, status, created_at) VALUES ('Legacy', 'pending', 'now')"
        )
    monkeypatch.setattr(task_app, "DATABASE", str(database))

    task_app.init_db()

    with task_app.get_db() as conn:
        task = conn.execute("SELECT * FROM tasks").fetchone()
        columns = {row["name"] for row in conn.execute("PRAGMA table_info(tasks)")}
    assert "owner_id" in columns
    assert task["title"] == "Legacy"
    assert task["owner_id"] is None

